import 'dart:convert';

/// Framework-agnostic HTTP response generated by MetaMantle SSR.
class ServerResponse {
  ServerResponse({
    required this.statusCode,
    Map<String, String>? headers,
    this.body = '',
    List<int>? bodyBytes,
  })  : headers = headers != null ? Map.from(headers) : {},
        bodyBytes = bodyBytes ?? utf8.encode(body);

  /// Creates a successful 200 OK HTML response.
  factory ServerResponse.okHtml(
    String html, {
    Map<String, String>? headers,
    String? etag,
    DateTime? lastModified,
    String? cacheControl,
  }) {
    final responseHeaders = <String, String>{
      'Content-Type': 'text/html; charset=utf-8',
      'Vary': 'Accept-Encoding',
      'X-Content-Type-Options': 'nosniff',
      if (headers != null) ...headers,
      if (etag != null) 'ETag': etag,
      if (lastModified != null)
        'Last-Modified': lastModified.toUtc().toIso8601String(),
      if (cacheControl != null) 'Cache-Control': cacheControl,
    };

    return ServerResponse(
      statusCode: 200,
      headers: responseHeaders,
      body: html,
    );
  }

  /// Creates a 304 Not Modified conditional response.
  factory ServerResponse.notModified({
    String? etag,
    DateTime? lastModified,
    String? cacheControl,
    Map<String, String>? headers,
  }) {
    return ServerResponse(
      statusCode: 304,
      headers: {
        if (etag != null) 'ETag': etag,
        if (lastModified != null)
          'Last-Modified': lastModified.toUtc().toIso8601String(),
        if (cacheControl != null) 'Cache-Control': cacheControl,
        if (headers != null) ...headers,
      },
      body: '',
    );
  }

  /// Creates a redirect response (301, 302, 307, 308).
  factory ServerResponse.redirect(
    String location, {
    int statusCode = 301,
    Map<String, String>? headers,
  }) {
    return ServerResponse(
      statusCode: statusCode,
      headers: {
        'Location': location,
        'Content-Type': 'text/plain; charset=utf-8',
        if (headers != null) ...headers,
      },
      body: 'Redirecting to $location...',
    );
  }

  /// Creates a 404 Not Found response.
  factory ServerResponse.notFound({
    String message = 'Page Not Found',
    String? html,
  }) {
    final bodyHtml = html ??
        '<!DOCTYPE html><html><head><title>404 Not Found</title></head><body><h1>404 — Page Not Found</h1><p>$message</p></body></html>';
    return ServerResponse(
      statusCode: 404,
      headers: {
        'Content-Type': 'text/html; charset=utf-8',
        'Cache-Control': 'no-cache, no-store, must-revalidate',
      },
      body: bodyHtml,
    );
  }

  /// Creates a 410 Gone response for permanently removed resources.
  factory ServerResponse.gone({
    String message = 'This resource has been permanently removed.',
    String? html,
  }) {
    final bodyHtml = html ??
        '<!DOCTYPE html><html><head><title>410 Gone</title></head><body><h1>410 — Resource Gone</h1><p>$message</p></body></html>';
    return ServerResponse(
      statusCode: 410,
      headers: {
        'Content-Type': 'text/html; charset=utf-8',
        'Cache-Control': 'public, max-age=86400',
      },
      body: bodyHtml,
    );
  }

  /// Creates a 500 Internal Server Error response.
  factory ServerResponse.serverError({
    String message = 'An unexpected error occurred.',
    String? html,
  }) {
    final bodyHtml = html ??
        '<!DOCTYPE html><html><head><title>500 Internal Server Error</title></head><body><h1>500 — Server Error</h1><p>$message</p></body></html>';
    return ServerResponse(
      statusCode: 500,
      headers: {
        'Content-Type': 'text/html; charset=utf-8',
        'Cache-Control': 'no-cache, no-store, must-revalidate',
      },
      body: bodyHtml,
    );
  }

  final int statusCode;
  final Map<String, String> headers;
  final String body;
  final List<int> bodyBytes;

  /// Retrieves an outgoing response header by name (case-insensitive).
  String? header(String name) {
    for (final entry in headers.entries) {
      if (entry.key.toLowerCase() == name.toLowerCase()) {
        return entry.value;
      }
    }
    return null;
  }
}
